import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.TWmUP5Ea.js";const u=JSON.parse('{"title":"Contributing","description":"","frontmatter":{"title":"Contributing"},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md"}'),n={name:"contributing.md"};function i(o,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="contributing-to-blank" tabindex="-1">Contributing to Blank <a class="header-anchor" href="#contributing-to-blank" aria-label="Permalink to &quot;Contributing to Blank&quot;">​</a></h1><p>Thanks for helping! Bug reports and ideas are best started as an <a href="https://github.com/FPurchess/blank/issues/new/choose" target="_blank" rel="noreferrer">issue</a>. For code, <a href="https://github.com/FPurchess/blank/fork" target="_blank" rel="noreferrer">fork the repository</a>, create a branch and open a pull request against <code>main</code>. Commit messages are a single line of the form <code>&lt;type&gt;: &lt;summary&gt;</code>, e.g. <code>fix: …</code>, <code>feat: …</code> or <code>docs: …</code>.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Blank is a <a href="https://tauri.app/" target="_blank" rel="noreferrer">Tauri 2</a> app with a TypeScript + <a href="https://prosemirror.net/" target="_blank" rel="noreferrer">ProseMirror</a> frontend in <code>src/</code>. You need <a href="https://bun.sh/" target="_blank" rel="noreferrer">bun</a>, <a href="https://www.rust-lang.org/tools/install" target="_blank" rel="noreferrer">Rust</a> and the <a href="https://tauri.app/start/prerequisites/" target="_blank" rel="noreferrer">Tauri prerequisites</a> of your system.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # run the app with hot reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # lint, format check and unit tests, same as the pre-commit hook</span></span></code></pre></div><p>Run <code>make</code> to list all tasks. They wrap the scripts in <code>package.json</code>, so <code>bun run &lt;script&gt;</code> works just as well, e.g. on Windows without <code>make</code>.</p><h2 id="end-to-end-tests" tabindex="-1">End-to-end tests <a class="header-anchor" href="#end-to-end-tests" aria-label="Permalink to &quot;End-to-end tests&quot;">​</a></h2><p>The tests in <a href="https://github.com/FPurchess/blank/tree/main/e2e" target="_blank" rel="noreferrer"><code>e2e/</code></a> drive the real app using <a href="https://tauri.app/develop/tests/webdriver/" target="_blank" rel="noreferrer"><code>tauri-driver</code></a> and <a href="https://webdriver.io/" target="_blank" rel="noreferrer">WebdriverIO</a>. They run on Linux only.</p><ol><li>Install the prerequisites: <code>sudo apt install webkit2gtk-driver xvfb</code> and <code>cargo install tauri-driver --locked</code></li><li>Build the app and run the tests: <code>make test-e2e</code>, or <code>make test-e2e-headless</code> without a display</li></ol><p>Set <code>E2E_SKIP_BUILD=1</code> to reuse an existing debug build. Set <code>E2E_PORT</code> to run on another port than 4444, e.g. next to a second checkout. Each spec file runs the app with a fresh, temporary profile, so your own documents and settings are left untouched.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>The website at <a href="https://fpurchess.github.io/blank/" target="_blank" rel="noreferrer">fpurchess.github.io/blank</a> lives in <a href="https://github.com/FPurchess/blank/tree/main/docs" target="_blank" rel="noreferrer"><code>docs/</code></a> and is built with <a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a>. Preview it with <code>make docs-dev</code>. If your change is visible to users, update the matching page in <code>docs/guide/</code>. After UI changes, regenerate the screenshots with <code>make docs-screenshots</code> (Linux, same prerequisites as the end-to-end tests).</p><h2 id="recommended-ide-setup" tabindex="-1">Recommended IDE setup <a class="header-anchor" href="#recommended-ide-setup" aria-label="Permalink to &quot;Recommended IDE setup&quot;">​</a></h2><p><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">VS Code</a> with the <a href="https://marketplace.visualstudio.com/items?itemName=tauri-apps.tauri-vscode" target="_blank" rel="noreferrer">Tauri</a> and <a href="https://marketplace.visualstudio.com/items?itemName=rust-lang.rust-analyzer" target="_blank" rel="noreferrer">rust-analyzer</a> extensions.</p>`,14)])])}const k=t(n,[["render",i]]);export{u as __pageData,k as default};
